sp_widget.client_script:
function($scope) {
  var c = this;
  c.tab = 'issue';
  c.stores = [];
  c.selectedStore = null;
  c.issueForm = {};
  c.equipForm = {};
  c.equipmentList = [];
  c.issueSubmitted = false;
  c.equipSubmitted = false;

  c.server.get({ action: 'get_my_stores' }).then(function(response) {
    c.stores = response.data.stores || [];
    if (c.stores.length > 0) {
      c.selectedStore = c.stores[0].sys_id;
      c.loadEquipment();
    }
  });

  c.onStoreChange = function() {
    c.loadEquipment();
  };

  c.loadEquipment = function() {
    c.server.get({ action: 'get_equipment', dark_store: c.selectedStore }).then(function(response) {
      c.equipmentList = response.data.equipment || [];
    });
  };

  c.submitIssue = function() {
    c.issueError = null;
    c.issueSubmitting = true;
    c.server.get({
      action: 'create_issue',
      dark_store: c.selectedStore,
      issue_category: c.issueForm.issue_category,
      severity: c.issueForm.severity,
      description: c.issueForm.description
    }).then(function(response) {
      c.issueSubmitting = false;
      if (response.data.success) {
        c.issueResult = response.data.result;
        c.issueSubmitted = true;
      } else {
        c.issueError = response.data.error || 'Could not log issue.';
      }
    }, function() {
      c.issueSubmitting = false;
      c.issueError = 'Could not reach the server.';
    });
  };

  c.resetIssue = function() {
    c.issueForm = {};
    c.issueSubmitted = false;
  };

  c.submitEquipment = function() {
    c.equipError = null;
    c.equipSubmitting = true;
    c.server.get({
      action: 'report_equipment_breakdown',
      dark_store: c.selectedStore,
      equipment_id: c.equipForm.equipment_id,
      description: c.equipForm.description
    }).then(function(response) {
      c.equipSubmitting = false;
      if (response.data.success) {
        c.equipResult = response.data.result;
        c.equipSubmitted = true;
      } else {
        c.equipError = response.data.error || 'Could not report breakdown.';
      }
    }, function() {
      c.equipSubmitting = false;
      c.equipError = 'Could not reach the server.';
    });
  };

  c.resetEquip = function() {
    c.equipForm = {};
    c.equipSubmitted = false;
    c.loadEquipment();
  };
}

sp_widget.script:
(function() {
  if (!input) return;

  function getMyStores() {
    var gr = new GlideRecord('x_2145749_qc_dark_store');
    gr.addQuery('manager', gs.getUserID());
    gr.orderBy('store_name');
    gr.setLimit(50);
    gr.query();
    var stores = [];
    while (gr.next()) {
      stores.push({ sys_id: gr.getUniqueValue() + '', store_name: gr.getValue('store_name') + '' });
    }
    return stores;
  }

  if (input.action === 'get_my_stores') {
    data.stores = getMyStores();
    return;
  }

  if (input.action === 'get_equipment') {
    var eqGr = new GlideRecord('x_2145749_qc_equipment');
    eqGr.addQuery('dark_store', input.dark_store);
    eqGr.setLimit(100);
    eqGr.query();
    var equipment = [];
    while (eqGr.next()) {
      equipment.push({
        sys_id: eqGr.getUniqueValue() + '',
        equipment_type: eqGr.getValue('equipment_type') + '',
        asset_tag: eqGr.getValue('asset_tag') + ''
      });
    }
    data.equipment = equipment;
    return;
  }

  if (input.action === 'create_issue') {
    if (!input.dark_store || !input.issue_category || !input.severity || !input.description) {
      data.success = false;
      data.error = 'All fields are required.';
      return;
    }
    var gr = new GlideRecord('x_2145749_qc_store_issue');
    gr.initialize();
    gr.setValue('dark_store', input.dark_store);
    gr.setValue('issue_category', input.issue_category);
    gr.setValue('severity', input.severity);
    gr.setValue('description', input.description);
    gr.setValue('state', 'open');
    gr.setValue('affects_pulse_score', true);
    var sysId = gr.insert();
    if (!sysId) {
      data.success = false;
      data.error = 'Could not create issue.';
      return;
    }
    data.success = true;
    data.result = { sys_id: sysId + '', number: gr.getValue('number') + '' };
    return;
  }

  if (input.action === 'report_equipment_breakdown') {
    if (!input.dark_store || !input.equipment_id || !input.description) {
      data.success = false;
      data.error = 'Equipment and description are required.';
      return;
    }
    // 1. Mark equipment as down
    var eqGr = new GlideRecord('x_2145749_qc_equipment');
    if (!eqGr.get(input.equipment_id)) {
      data.success = false;
      data.error = 'Equipment record not found.';
      return;
    }
    eqGr.setValue('operational_status', 'down');
    eqGr.update();

    // 2. Auto-create linked store_issue
    var issueGr = new GlideRecord('x_2145749_qc_store_issue');
    issueGr.initialize();
    issueGr.setValue('dark_store', input.dark_store);
    issueGr.setValue('equipment', input.equipment_id);
    issueGr.setValue('issue_category', 'equipment_breakdown');
    issueGr.setValue('severity', 'high');
    issueGr.setValue('description', input.description);
    issueGr.setValue('state', 'open');
    issueGr.setValue('affects_pulse_score', true);
    var issueSysId = issueGr.insert();
    if (!issueSysId) {
      data.success = false;
      data.error = 'Equipment marked down, but issue creation failed.';
      return;
    }
    data.success = true;
    data.result = { sys_id: issueSysId + '', number: issueGr.getValue('number') + '' };
  }
})();
